    nxt = {}
    for a in colors:
        options = [(counts.get((a, b), 0), b) for b in colors if b != a]
        if options:
            nxt[a] = max(options)[1]

    def advance(value, steps):
        if steps >= 0:
            for _ in range(steps):
                value = nxt.get(value, value)
        else:
            for _ in range(-steps):
                prevs = [a for a, b in nxt.items() if b == value]
                if prevs:
                    value = prevs[0]
        return value

    out = [row[:] for row in grid]
