        if choices:
            successor[a] = max(choices)[1]

    predecessor = {}
    for a, b in successor.items():
        predecessor[b] = a

    def move(value, steps):
        for _ in range(abs(steps)):
            if steps > 0:
                value = successor.get(value, value)
            else:
                value = predecessor.get(value, value)
        return value

    out = [row[:] for row in grid]
    for r in range(h):
